import math

mode = 'FORWARD'
fwd_start_prog = None

def control(obs):
    global mode, fwd_start_prog
    status = obs.get('status')
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    covered = obs.get('progress', {}).get('covered', 10.1)
    look_deg = -23.0

    if fwd_start_prog is None:
        fwd_start_prog = covered

    # If PINNED or still on contact penalty, shift to forward gear immediately
    if status == 'PINNED' or hold_s > 0.0:
        mode = 'FORWARD'
        return {
            'steer_deg': -15.0,
            'speed_mps': 1.0,
            'look_deg': look_deg
        }

    if mode == 'FORWARD':
        # Pull forward ~2.5m or until hitch straightens and we moved forward at least 1.5m
        if covered <= fwd_start_prog - 2.5 or (abs(hitch) < 4.0 and covered <= fwd_start_prog - 1.5):
            mode = 'REVERSE'
        else:
            # Pull forward while steering right to shift the rig away from the left barrier
            return {
                'steer_deg': -18.0,
                'speed_mps': 1.0,
                'look_deg': look_deg
            }

    # REVERSE MODE
    cam = obs.get('views', {}).get('camera')
    th = math.radians(-hitch)
    cos_th = math.cos(th)
    sin_th = math.sin(th)

    left_clearance = 999.0
    right_clearance = 999.0

    if cam and 'walls' in cam:
        for b_deg, dist in cam['walls']:
            b = math.radians(b_deg)
            dx_v = dist * math.cos(b)
            dy_v = dist * math.sin(b)
            x_t = dx_v * cos_th + dy_v * sin_th
            y_t = -dx_v * sin_th + dy_v * cos_th

            if -6.0 < x_t < -0.2:
                if y_t > 0:
                    left_clearance = min(left_clearance, y_t)
                else:
                    right_clearance = min(right_clearance, -y_t)

    # Target hitch to center trailer between rails
    target_hitch = 0.0
    if left_clearance < 900 and right_clearance < 900:
        err_y = left_clearance - right_clearance
        target_hitch = max(-15.0, min(15.0, err_y * 12.0))
    elif left_clearance < 1.3:
        target_hitch = -10.0
    elif right_clearance < 1.3:
        target_hitch = 10.0

    hitch_err = hitch - target_hitch
    target_steer = max(-30.0, min(30.0, hitch_err * 2.5))

    return {
        'steer_deg': target_steer,
        'speed_mps': -0.45,
        'look_deg': look_deg
    }

