    hold_s = obs.get('motion', {}).get('hold_s', 0.0)

    if start_prog is None:
        start_prog = covered

    # During hold penalty / gear change, initiate forward crawl
    if hold_s > 0.0:
        return {'steer_deg': 12.0, 'speed_mps': 0.6, 'look_deg': look_deg}

    # Pull forward curving slightly left to pull away from the left barrier
    if state == 'PULL_FWD':
        if covered <= start_prog - 2.8:
            state = 'REVERSE'
        else:
            return {'steer_deg': 12.0, 'speed_mps': 0.6, 'look_deg': look_deg}

    # Reversing through the corner
    cam = obs.get('views', {}).get('camera')
    th = math.radians(-hitch)
    cos_th = math.cos(th)
    sin_th = math.sin(th)

    left_clearance = 999.0
    right_clearance = 999.0

    if cam and 'walls' in cam:
        for b_deg, dist in cam['walls']:
            b = math.radians(b_deg)
            dx_v = dist * math.cos(b)
            dy_v = dist * math.sin(b)
            x_t = dx_v * cos_th + dy_v * sin_th
            y_t = -dx_v * sin_th + dy_v * cos_th

            if -3.0 < x_t < 0.2:
                if y_t > 0:
                    left_clearance = min(left_clearance, y_t - 0.85)
                else:
                    right_clearance = min(right_clearance, -y_t - 0.85)

    diff = left_clearance - right_clearance
    if left_clearance < 900 and right_clearance < 900:
        target_hitch = -10.0 + diff * 12.0
    else:
        target_hitch = -8.0

    if left_clearance < 0.35:
        target_hitch = max(target_hitch, -2.0)
    elif right_clearance < 0.35:
        target_hitch = min(target_hitch, -16.0)

    target_hitch = max(-20.0, min(0.0, target_hitch))

    hitch_err = hitch - target_hitch
    target_steer = max(-25.0, min(25.0, hitch_err * 2.2))

    return {
        'steer_deg': target_steer,
        'speed_mps': -0.35,
        'look_deg': look_deg
    }

