import math

state = 'PULL_FWD'

def control(obs):
    global state
    look_deg = -23.0
    hitch = obs.get('hitch_deg', 0.0)
    covered = obs.get('progress', {}).get('covered', 9.4)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)

    # Rail touches: 7/8. We have ONLY 1 TOUCH REMAINING! Must be zero contact!
    if hold_s > 0.0:
        return {'steer_deg': -10.0, 'speed_mps': 0.5, 'look_deg': look_deg}

    # Step 1: Pull forward to ~6.0m while steering right (-12 deg) to get away from the left wall
    if state == 'PULL_FWD':
        if covered <= 6.2:
            state = 'REVERSE'
        else:
            # Gentle forward steer to shift right without hitting right front corner
            return {'steer_deg': -10.0, 'speed_mps': 0.5, 'look_deg': look_deg}

    # Step 2: In reverse mode, check camera clearances
    cam = obs.get('views', {}).get('camera')
    th = math.radians(-hitch)
    cos_th = math.cos(th)
    sin_th = math.sin(th)

    left_clearance = 999.0
    right_clearance = 999.0

    if cam and 'walls' in cam:
        for b_deg, dist in cam['walls']:
            b = math.radians(b_deg)
            dx_v = dist * math.cos(b)
            dy_v = dist * math.sin(b)
            x_t = dx_v * cos_th + dy_v * sin_th
            y_t = -dx_v * sin_th + dy_v * cos_th

            # Trailer body / immediate rear
            if -3.5 < x_t < 0.2:
                if y_t > 0:
                    left_clearance = min(left_clearance, y_t - 0.85)
                else:
                    right_clearance = min(right_clearance, -y_t - 0.85)

    # Target hitch trajectory:
    # In straight stretch (< 8.5m), hitch ~ 0
    # Transition (8.5m - 10.5m), hitch gently turns to -6
    # Deep in turn (> 10.5m), hitch ~ -10 to -12
    if covered < 8.5:
        target_hitch = 0.0
    elif covered < 10.5:
        target_hitch = -6.0
    else:
        target_hitch = -10.0

    # Clearance protection:
    if left_clearance < 0.55:
        target_hitch = max(target_hitch, 0.0)
    elif right_clearance < 0.40:
        target_hitch = min(target_hitch, -14.0)

    # Hitch error feedback
    hitch_err = hitch - target_hitch
    target_steer = max(-24.0, min(24.0, hitch_err * 2.2))

    return {
        'steer_deg': target_steer,
        'speed_mps': -0.32,
        'look_deg': look_deg
    }

