import math

state = {
    'is_pulling_forward': False,
    'pull_fwd_time': 0.0,
}

def control(obs):
    t = obs.get('t', 0.0)
    dt = obs.get('dt', 0.1)
    status = obs.get('status', '')
    hitch = obs.get('hitch_deg', 0.0)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)

    look_deg = -64.0 if int(t / 2.5) % 2 == 0 else 64.0

    if status in ('PINNED', 'JACKKNIFED') or hold_s > 0.05:
        if hold_s > 0.05:
            return {'steer_deg': 20.0, 'speed_mps': 0.0, 'look_deg': look_deg}
        else:
            state['is_pulling_forward'] = True
            state['pull_fwd_time'] = 3.0

    if state.get('is_pulling_forward', False):
        state['pull_fwd_time'] -= dt
        if state['pull_fwd_time'] <= 0:
            state['is_pulling_forward'] = False
        else:
            return {'steer_deg': 20.0, 'speed_mps': 1.0, 'look_deg': 0.0}

    speed = -0.75

    views = obs.get('views', {})
    trailer_rear = obs.get('rig', {}).get('trailer_rear', [-6.3, 0.0])
    tr_x, tr_y = trailer_rear[0], trailer_rear[1]

    left_dist = 4.0
    right_dist = 4.0

    for v_name, view in views.items():
        origin = view.get('origin', [0.0, 0.0])
        walls = view.get('walls', [])
        for b_deg, d in walls:
            b_rad = math.radians(b_deg)
            px = origin[0] + d * math.cos(b_rad)
            py = origin[1] + d * math.sin(b_rad)
            if tr_x - 4.0 < px < tr_x + 3.0:
                dy = py - tr_y
                if dy > 0 and dy < left_dist:
                    left_dist = dy
                elif dy < 0 and (-dy) < right_dist:
                    right_dist = -dy

    target = obs.get('target', {})
    has_target = target.get('in_sight', False)
    target_bearing = target.get('bearing_deg', None)

    if has_target and target_bearing is not None:
        err = target_bearing - 180.0 if target_bearing > 0 else target_bearing + 180.0
        desired_hitch = -err * 0.45
    else:
        corridor_err = max(-1.2, min(1.2, left_dist - right_dist))
        desired_hitch = corridor_err * 6.0

    desired_hitch = max(-16.0, min(16.0, desired_hitch))

    hitch_err = hitch - desired_hitch
    steer = 1.7 * hitch_err
    steer = max(-40.0, min(40.0, steer))

    return {
        'steer_deg': steer,
        'speed_mps': speed,
        'look_deg': look_deg
    }

