    global phase, fwd_dist, last_prog

    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    look_deg = 165.0
    prog = obs.get('progress', {}).get('covered', 0.0)
    rem = obs.get('progress', {}).get('remaining', 3.5)
    hitch = obs['hitch_deg']

    if last_prog is None:
        last_prog = prog
    d_m = abs(prog - last_prog)
    last_prog = prog

    if hold_s > 0:
        return {'steer_deg': -10.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    if phase == 'UNPIN_FWD':
        fwd_dist += d_m
        if fwd_dist < 1.2:
            return {'steer_deg': -16.0, 'speed_mps': 0.5, 'look_deg': look_deg}
        elif fwd_dist < 2.4:
